'use strict';

/**
* Serialize a k-means clustering results object as a JSON object.
*
* @module @stdlib/ml/base/kmeans/results/to-json
*
* @example
* var res2json = require( '@stdlib/ml/base/kmeans/results/to-json' );
*
* var results = {
*     'replicates': 4,
*     'replicate': 2,
*     'metric': 'sqeuclidean',
*     'iterations': 10,
*     'algorithm': 'lloyd',
*     'inertia': 3.28,
*     'k': 4,
*     'samples': 10,
*     'features': 3,
*     'method': 'K-means clustering'
* };
*
* var obj = res2json( results );
* // returns {...}
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
